/* Lightweight checks for the local-only email previews generated by renderEmailPreviews.js. */
const fs = require('fs');
const path = require('path');
const {
  escapeHtml,
  formatTableLabel,
  primaryButton,
  summaryBox,
  tokenBox,
} = (() => {
  const helpers = require('../src/services/emailTemplateHelpers');
  return {
    ...helpers,
    formatTableLabel: require('../src/utils/tableLabel').formatTableLabel,
  };
})();

const previewDir = path.resolve(__dirname, '../../email-previews/after');
const manifest = JSON.parse(fs.readFileSync(path.join(previewDir, 'manifest.json'), 'utf8'));
const expectedTemplates = [
  'otp-verification',
  'order-confirmed',
  'payment-confirmed',
  'order-ready',
  'order-completed',
  'order-cancelled',
];

if (manifest.length !== expectedTemplates.length) {
  throw new Error(`Expected ${expectedTemplates.length} previews; found ${manifest.length}.`);
}

for (const name of expectedTemplates) {
  const html = fs.readFileSync(path.join(previewDir, `${name}.html`), 'utf8');
  const text = fs.readFileSync(path.join(previewDir, `${name}.txt`), 'utf8');
  if (Buffer.byteLength(html, 'utf8') >= 100 * 1024) throw new Error(`${name}.html is at least 100 KB.`);
  if (!/^<!doctype html>/i.test(html) || !/<html\b/i.test(html) || !/<\/html>/i.test(html)) {
    throw new Error(`${name}.html is missing its HTML document structure.`);
  }
  if (/<script\b|<link\b[^>]*stylesheet|var\s*\(/i.test(html)) {
    throw new Error(`${name}.html uses script, external CSS, or CSS variables.`);
  }
  if (/\bundefined\b|\bnull\b/i.test(html) || /order\s*type|dine[\s-]?in|takeaway/i.test(`${html}\n${text}`)) {
    throw new Error(`${name} exposes a missing value or unsupported order type.`);
  }
  if (!text.trim()) throw new Error(`${name}.txt is empty.`);

  const links = [...html.matchAll(/\b(?:href|src)="([^"]+)"/gi)].map((match) => match[1]);
  for (const link of links) {
    let url;
    try { url = new URL(link); } catch { throw new Error(`${name} contains an invalid link: ${link}`); }
    if (!['http:', 'https:'].includes(url.protocol)) throw new Error(`${name} has an unsupported link: ${link}`);
    if (url.hostname === 'localhost' || url.hostname.endsWith('.invalid')) {
      throw new Error(`${name} contains a placeholder or local-only link: ${link}`);
    }
  }
}

if (formatTableLabel({ tableLabel: '' }) !== 'Counter') throw new Error('Legacy table label must fall back to Counter.');
if (formatTableLabel({ tableLabel: '19' }) !== 'Table 19') throw new Error('Stored table label must render as Table 19.');
if (escapeHtml('<img src=x onerror="alert(1)">') !== '&lt;img src=x onerror=&quot;alert(1)&quot;&gt;') {
  throw new Error('Dynamic HTML escaping check failed.');
}
if (summaryBox([['Optional value', undefined]]).includes('undefined')) {
  throw new Error('Missing summary values must be hidden.');
}
if (!tokenBox('<482916>').includes('&lt;482916&gt;')) throw new Error('Token values must be escaped once.');
if (!primaryButton('https://example.com/?a=1&b=2', 'Open').includes('&amp;b=2')) {
  throw new Error('Button query strings must be safely HTML-escaped.');
}

console.log(`Checked ${expectedTemplates.length} HTML and plain-text email previews; links, size, escaping, and legacy table fallback passed.`);
